from pathlib import Path
import json
R=Path(__file__).resolve().parents[1]
m=json.loads((R/'manifest.json').read_text())
familylabels={'panel':'面板底板','title':'标题底板','well':'内容凹槽','divider':'分隔线','button-primary':'主要按钮','button-secondary':'次要按钮','close':'关闭按钮','tab':'页签','item-slot':'物品格','recipe-card':'配方卡','queue-slot':'队列槽位','quantity':'数量标签','progress':'进度轨道与填充','notice':'局部提示','symbol':'状态标识','canopy':'条纹布棚边','linen-corner':'亚麻布角'}
familylabels.update({'shelf-card':'商品货架格','order-paper':'订单纸单','detail-paper':'详情纸签','stepper':'数量加减底板','slider-track':'滑条轨道','slider-thumb':'滑条木珠','checkbox':'留种勾选框','resource-pill':'资源标签','toast-paper':'轻提示纸片','ribbon':'状态布签'})
statelabels={'default':'默认','selected':'选中','pressed':'按下','disabled':'禁用','missing':'缺料','empty':'空槽 / 空状态','running':'生产中','waiting':'等待','complete':'已完成','locked':'未解锁','info':'提示','full':'满仓','track':'轨道','fill':'填充','lock':'锁定','clock':'时间','plus':'添加','warning':'提醒','arrow':'进入'}
rows=[]
for family,title in familylabels.items():
 cards=[]
 for x in m['components']:
  if x['family']!=family:continue
  cards.append(f'<a class="spec-card" href="{x["file"]}" target="_blank"><div class="component-well"><img src="{x["file"]}" alt="{title} · {statelabels.get(x["state"],x["state"])}"></div><b>{title} · {statelabels.get(x["state"],x["state"])}</b><small>{x["canvas"][0]} × {x["canvas"][1]} · {"九宫格" if x["nineSlice"] else "横向拉伸" if x.get("scaling")=="stretch-x" else "等比缩放"}</small><code>{x["id"]}</code></a>')
 rows.append("".join(cards))
styles='''*{box-sizing:border-box}body{margin:0;background:#f1eddf;color:#604e3c;font:14px/1.6 'PingFang SC',system-ui,sans-serif}main{max-width:1320px;margin:auto;padding:34px 28px 72px}h1{font-size:30px;line-height:1.3;letter-spacing:1px;margin:10px 0}h2{font-size:22px;margin:30px 0 8px}p{color:#8b7963;margin:8px 0}.eyebrow{font-size:12px;letter-spacing:2px;color:#829469}.intro{display:flex;justify-content:space-between;align-items:end;gap:20px}.tag{display:inline-block;padding:5px 12px;border-radius:99px;background:#dfe7cf;color:#6b7d54;font-size:12px}.links{display:flex;gap:10px;flex-wrap:wrap;margin:18px 0}a{color:inherit;text-decoration:none}.links a,.state-bar a{padding:8px 14px;border:1px solid #c8b89c;border-radius:12px;background:#fff9ec}.sample-grid{display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:22px;align-items:start}.sample{background:#fffaf0;border:1px solid #d3c5ac;border-radius:20px;padding:14px;overflow:hidden}.sample img{width:100%;display:block;border-radius:10px}.sample h3{margin:0 0 10px;font-size:16px}.sample p{font-size:12px}.sample a{display:block}.sample.mobile img{max-height:555px;object-fit:contain}.sample-note{padding:20px 0;border-top:1px solid #d8ccb6;margin-top:18px;display:grid;grid-template-columns:repeat(3,1fr);gap:20px}.sample-note h3{font-size:15px;margin:0 0 4px}.sample-note p{font-size:13px}.state-bar{display:flex;flex-wrap:wrap;gap:8px;margin:16px 0}.component-table{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:18px;padding:20px;background:#fffaf0;border:1px solid #d8ccb6;border-radius:18px}.family{margin:18px 0;padding:20px;background:#fffaf0;border:1px solid #d8ccb6;border-radius:18px}.family h3{font-size:16px;margin:0 0 14px}.component-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:14px}.spec-card{display:block;min-width:0}.component-well{height:112px;display:grid;place-items:center;background:#ece9dd;border-radius:12px;padding:8px}.component-well img{max-width:130px;max-height:96px;min-height:4px;object-fit:contain}.spec-card b{display:block;font-size:12px;margin-top:7px}.spec-card small{display:block;font-size:11px;color:#948069}.spec-card code{font-size:9px;color:#a18e76;word-break:break-all}.states{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.states article{background:#fffaf0;padding:12px;border:1px solid #d8ccb6;border-radius:14px}.states img{width:100%;display:block}.states h3{font-size:14px;margin:6px 0}.states p{font-size:12px}.reuse{display:flex;gap:12px;flex-wrap:wrap;padding:18px;background:#fffaf0;border:1px solid #d8ccb6;border-radius:16px}.reuse img{width:48px;height:48px;object-fit:contain}.notice{background:#e5ead8;border-radius:14px;padding:14px 18px;font-size:13px;color:#657652}footer{margin-top:32px;font-size:12px;color:#8f7d65}@media(max-width:800px){main{padding:24px 14px}.sample-grid{grid-template-columns:1fr}.sample.mobile{max-width:430px}.sample.mobile img{max-height:none}.sample-note{grid-template-columns:1fr;gap:10px}.states{grid-template-columns:repeat(2,1fr)}.intro{display:block}h1{font-size:26px}}'''
reuse=json.loads((R/'reuse-manifest.json').read_text())
html=f'''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>羊羊牧场 · 生产面板与组件样板</title><style>{styles}</style><main>
<div class="intro"><div><span class="eyebrow">羊羊牧场 / UI ART SAMPLE 01</span><h1>生产面板 · 农场小工坊</h1><p>浅木框 · 条纹布棚 · 夹签食谱 · 木箱槽位</p></div><span class="tag">P0 已扩展 · 附 P1 / P2 资源</span></div>
<div class="links"><a href="expansion.html">查看本轮扩展 →</a><a href="landscape.html">自然过渡与短效果</a><a href="sample.html" target="_blank">打开可操作样板 ↗</a><a href="comparison.html">查看上一版对照</a><a href="#components">查看组件表</a><a href="README.md">交付说明</a><a href="manifest.json">切片与尺寸清单</a><a href="environment-review.html">已有环境核对</a><a href="source/production-wide.svg">宽屏可编辑 SVG</a><a href="source/production-mobile.svg">手机可编辑 SVG</a></div>
<div class="sample-grid"><article class="sample"><h3>宽屏 / 1280 × 720</h3><a href="sample.html" target="_blank"><img src="previews/production-wide.png" alt="宽屏生产面板组合"></a><p>面板靠右，约六成画面继续显示农场；配方与所需材料就近查看。</p><div class="sample-note"><div><h3>信息分区</h3><p>选配方、核对材料、查看队列，顺着一个方向完成。</p></div><div><h3>少一点遮挡</h3><p>短提示靠近对应物品，完成品托盘始终独立。</p></div><div><h3>相同组件</h3><p>面板、按钮和物品格可以继续用于仓库与商店。</p></div></div></article><article class="sample mobile"><h3>手机 / 400 × 740</h3><a href="mobile.html" target="_blank"><img src="previews/production-mobile.png" alt="400px手机生产面板组合"></a><p>内容向下排列，顶部和主操作固定；矮屏时中部独立滚动。</p></article></div>
<h2>必要状态，也一起看</h2><p>所有文案、数量、时间、进度均为可编辑文字或独立组件。下方链接可以交互切换配方。</p><div class="state-bar"><a href="mobile.html?state=normal" target="_blank">材料齐备</a><a href="mobile.html?state=missing" target="_blank">缺少材料</a><a href="mobile.html?state=full" target="_blank">货仓已满</a><a href="mobile.html?state=empty" target="_blank">暂无可做配方</a><a href="mobile.html?state=long" target="_blank">长文案适配</a></div>
<div class="states">{''.join(f'<article><img src="previews/mobile-{s}.png" alt="{t}手机版"><h3>{t}</h3><p>{d}</p></article>' for s,t,d in [('missing','缺少材料','缺口写在原料旁，保留获取入口。'),('full','货仓已满','成品继续保留，满仓提示靠近领取区。'),('empty','暂无可做配方','保留全部配方入口和现有队列。'),('long','长文案','较长名称和按钮文字仍有清楚边界。')])}</div>
<h2 id="components">完整组件集 / 27 类 · 84 个状态文件</h2><p>独立透明 SVG，无文字和物品图标；可拉伸组件有九宫格、内边距及内容安全区。点击可查看原文件。</p><div class="component-table">{''.join(rows)}</div>
<h2>直接复用的素材</h2><div class="reuse">{''.join(f'<img src="{x["file"]}" alt="{x["id"]}">' for x in reuse)}</div><p>21 个已有物品图标和 9 个建筑缩略图，逐字节保留。对照来源见 <a href="reuse-manifest.json"><u>复用清单</u></a>。</p>
<div class="notice">方向已确认：商店、仓库、订单组合和地形过渡、短效果已完成。见扩展总览；全部仍为独立美术资源。</div><footer>扩展依据 main 6f195a1 · 仅美术交付与独立预览 · 不读写游戏存档 · 原素材和游戏代码保持不变。</footer></main></html>'''
(R/'index.html').write_text(html)
print('gallery built')
